local function ItemSpellPT(name)
    if type(name) ~= "string" or name == "" then return nil end
    local fixed = CUSTOM_ITEM_SPELL_FIX[name]
    if fixed then return fixed end
    local value = AscensionPTBR.SpellNameEN2ES and AscensionPTBR.SpellNameEN2ES[name]
    if type(value) == "string" and value ~= "" and value ~= name then return value end
    return nil
end

