local ITEM_RECIPE_PREFIX_PT = {
    ["Pattern: "]="Molde: ", ["Plans: "]="Instruções: ", ["Formula: "]="Fórmula: ",
    ["Recipe: "]="Receita: ", ["Design: "]="Desenho: ", ["Schematic: "]="Esquema: ",
}

local function IsInternalItemName(en)
    return en:find("TEST", 1, true) or en:find("Test", 1, true) or en:find("DND", 1, true)
        or en:find("WIP", 1, true) or en:find("[MISSING ITEM NAME]", 1, true)
        or en:find("RPGITEM", 1, true) or en:find("Monster -", 1, true)
end

local function StructuredGearNamePT(en)
    if type(en) ~= "string" or en == "" or IsInternalItemName(en) then return nil end

    -- Receitas: traduz o tipo e, quando o produto segue um conjunto conhecido,
    -- traduz o produto também.
    for enPrefix, ptPrefix in pairs(ITEM_RECIPE_PREFIX_PT) do
        if en:sub(1, #enPrefix) == enPrefix then
            local rest = en:sub(#enPrefix + 1)
            local restPT = StructuredGearNamePT(rest) or CUSTOM_ITEM_EXACT_PT[rest] or ItemSpellPT(rest)
            if restPT then return ptPrefix .. restPT end
        end
    end

    -- Ex.: Handwraps of Prophecy / Belt of Wrath / Headguard of Ten Storms.
    -- O item-base e o conjunto já têm nomenclatura validada; apenas combinamos
    -- as duas partes, sem tradução livre de nomes próprios.
    local firstSlot, familyOf = en:match("^([%a%-]+)%s+of%s+(.+)$")
    local firstSlotPT = firstSlot and ITEM_SLOT_PT[firstSlot]
    local familyOfPT = familyOf and ITEM_SET_SUFFIX_PT[familyOf]
    if firstSlotPT and familyOfPT then return firstSlotPT .. " " .. familyOfPT end

    local modifier, slot = en:match("^(.+)%s+([%a%-]+)$")
    local slotPT = slot and ITEM_SLOT_PT[slot]
    if not (modifier and slotPT) then return nil end

    local suffix = ITEM_SET_SUFFIX_PT[modifier]
    if suffix then return slotPT .. " " .. suffix end

    -- Ex.: Mourner's Cloak / Niko's Amulet / Champion's Blade.
    local owner = modifier:match("^(.+)'s$")
    if owner and ITEM_OWNER_SUFFIX_PT[owner] then
        return slotPT .. " " .. ITEM_OWNER_SUFFIX_PT[owner]
    end
    -- Plural possessivo: Combatants' ...
    owner = modifier:match("^(.+)'$")
    if owner and ITEM_OWNER_SUFFIX_PT[owner] then
        return slotPT .. " " .. ITEM_OWNER_SUFFIX_PT[owner]
    end

    -- Ex.: Grand Marshal's Chain Helmet / Combatants' Dragonleather Handguards.
    local possessiveOwner, family = modifier:match("^(.+)'s%s+(.+)$")
    if not possessiveOwner then possessiveOwner, family = modifier:match("^(.+)'%s+(.+)$") end
    local ownerPT = possessiveOwner and ITEM_OWNER_SUFFIX_PT[possessiveOwner]
    local familyPT = family and ITEM_ARMOR_FAMILY_PT[family]
    if ownerPT and familyPT then return slotPT .. " " .. familyPT .. " " .. ownerPT end

    -- Alguns conjuntos usam "Azshara Conqueror's ..." e equivalentes.
    if family then
        local nestedSuffix = ITEM_SET_SUFFIX_PT[family]
        if ownerPT and nestedSuffix then return slotPT .. " " .. nestedSuffix .. " " .. ownerPT end
    end

    return nil
end


