function AscensionPTBR.TranslateCustomItemName(en)
    if type(en) ~= "string" or en == "" then return nil end

    -- Itens de sistema mudam de ID entre snapshots/realms. Nome atual do cliente
    -- e a chave mais segura aqui; um hash lookup custa O(1) e nao cria varredura.
    local exactPT = CUSTOM_ITEM_EXACT_PT[en]
    if exactPT then return exactPT end

    local structuredPT = StructuredGearNamePT(en)
    if structuredPT then return structuredPT end

    -- Skill Cards atuais do CoA. Usa o mesmo glossario das habilidades da addon.
    local spell = en:match("^Lucky Golden Skill Card%s*%-%s*(.+)$")
    if spell then
        local pt = ItemSpellPT(spell)
        if pt then return "Carta Dourada de Habilidade da Sorte — " .. pt end
    end
    spell = en:match("^Lucky Skill Card%s*%-%s*(.+)$")
    if spell then
        local pt = ItemSpellPT(spell)
        if pt then return "Carta de Habilidade da Sorte — " .. pt end
    end
    spell = en:match("^Golden Skill Card%s*%-%s*(.+)$")
    if spell then
        local pt = ItemSpellPT(spell)
        if pt then return "Carta Dourada de Habilidade — " .. pt end
    end
    spell = en:match("^Skill Card%s*%-%s*(.+)$")
    if spell then
        local pt = ItemSpellPT(spell)
        if pt then return "Carta de Habilidade — " .. pt end
    end

    spell = en:match("^Mystic Scroll:%s*(.+)$")
    if spell then
        local pt = ItemSpellPT(spell)
        if pt then return "Pergaminho Místico: " .. pt end
    end

    spell = en:match("^Tome of%s+(.+)$")
    if spell then
        local pt = ItemSpellPT(spell)
        if pt then return "Tomo de " .. pt end
    end

    local family, tomeSpell = en:match("^(.+)%s+Tome:%s*(.+)$")
    if family and tomeSpell then
        local spellPT = ItemSpellPT(tomeSpell)
        if spellPT then
            local familyPT = CUSTOM_CLASS_PT[family] or ItemSpellPT(family)
            if family == "Felforged" then familyPT = "Vilforjado" end
            if familyPT then return familyPT .. " — Tomo: " .. spellPT end
        end
    end

    -- Bundles continuam funcionando mesmo se o ID mudar em uma temporada nova.
    local bundleClass = en:match("^(.+)%s+Elite Class Bundle$")
    if bundleClass and CUSTOM_CLASS_PT[bundleClass] then
        return "Pacote de Classe Elite — " .. CUSTOM_CLASS_PT[bundleClass]
    end
    bundleClass = en:match("^(.+)%s+Class Bundle$")
    if bundleClass and CUSTOM_CLASS_PT[bundleClass] then
        return "Pacote de Classe — " .. CUSTOM_CLASS_PT[bundleClass]
    end

    local pouchAmount = en:match("^Rune of Ascension Pouch%s*%(([%d,%.]+)%)$")
    if pouchAmount then
        return "Bolsa de Runas da Ascensão (" .. pouchAmount:gsub(",", ".") .. ")"
    end
    pouchAmount = en:match("^Boss Blitz Rune of Ascension Pouch%s*%(([%d,%.]+)%)$")
    if pouchAmount then
        return "Bolsa de Runas da Ascensão — Boss Blitz (" .. pouchAmount:gsub(",", ".") .. ")"
    end
    pouchAmount = en:match("^Mystic Rune Pouch%s*%(([%d,%.]+)%)$")
    if pouchAmount then
        return "Bolsa de Runas Místicas (" .. pouchAmount:gsub(",", ".") .. ")"
    end
    pouchAmount = en:match("^Mystic Orb Pouch%s*%(([%d,%.]+)%)$")
    if pouchAmount then
        return "Bolsa de Orbes Místicos (" .. pouchAmount:gsub(",", ".") .. ")"
    end

    -- Cartas seladas/pacotes: vocabulário fixo do sistema, sem depender de ID.
    if en == "Sealed Card" then return "Carta Selada" end
    local rarity, rest = en:match("^(%S+)%s+(.+)$")
    local rarityF = { Uncommon="Incomum", Rare="Rara", Epic="Épica", Legendary="Lendária" }
    local rarityP = { Uncommon="Incomuns", Rare="Raras", Epic="Épicas", Legendary="Lendárias" }
    if rarityF[rarity] and rest and rest:find("Sealed", 1, true) and rest:find("Card", 1, true) then
        local isPack = rest:sub(-5) == " Pack"
        local ability = rest:find("Ability", 1, true)
        local talent = rest:find("Talent", 1, true)
        local golden = rest:find("Golden", 1, true)
        local lucky = rest:find("Lucky", 1, true)
        local felforged = rest:find("Felforged", 1, true)
        local out = isPack and "Pacote de Cartas Seladas" or "Carta Selada"
        if ability then out = out .. " de Habilidade" elseif talent then out = out .. " de Talento" end
        if golden then out = out .. (isPack and " Douradas" or " Dourada") end
        if lucky then out = out .. " da Sorte" end
        if felforged then out = out .. (isPack and " Vilforjadas" or " Vilforjada") end
        return out .. " " .. (isPack and rarityP[rarity] or rarityF[rarity])
    end

    if en == "Mark of Ascension" then return "Marca da Ascensão" end
    if en == "Rune of Ascension" then return "Runa da Ascensão" end
    if en == "Spirit Crystal" then return "Cristal Espiritual" end

    -- Forged existem em grande volume. Reaproveita a traducao do item-base sob
    -- demanda e o Core memoriza o resultado depois do primeiro hover.
    local forgedBase = en:match("^Bloodforged%s+(.+)$")
    if forgedBase and AscensionPTBR.TranslateItemNameText then
        local ok, basePT = pcall(AscensionPTBR.TranslateItemNameText, forgedBase)
        if ok and type(basePT) == "string" and basePT ~= "" and basePT ~= forgedBase then
            return "Forjado em Sangue: " .. basePT
        end
    end

    local worldBase = en:match("^Worldforged%s+(.+)$")
    if worldBase and AscensionPTBR.TranslateItemNameText then
        local ok, basePT = pcall(AscensionPTBR.TranslateItemNameText, worldBase)
        if ok and type(basePT) == "string" and basePT ~= "" and basePT ~= worldBase then
            return "Forjado pelo Mundo: " .. basePT
        end
    end

    local felBase = en:match("^Felforged%s+(.+)$")
    if felBase and AscensionPTBR.TranslateItemNameText then
        local ok, basePT = pcall(AscensionPTBR.TranslateItemNameText, felBase)
        if ok and type(basePT) == "string" and basePT ~= "" and basePT ~= felBase then
            return "Vilforjado: " .. basePT
        end
    end

    return nil
end
